			written = { ["Back up to the top of the keep: each player takes {quest:2991} from {npc:8022} (it cannot be shared). {npc:7796} is fought in Zul'Farrak in Group 24, and {npc:8022} takes the medallion back in Group 25."] = "Back up to the top of the keep: each player takes Nekrum's Medallion from Thadius (it cannot be shared). Nekrum Gutchewer is fought in Zul'Farrak in Group 24, and Thadius takes the medallion back in Group 25.", ["Ride north to Skulk Rock in the middle of the {zone:1425}. Green Sludges and Jade Oozes crawl all around it.\nCareful: Panthers move around the area in stealth."] = "Ride north to Skulk Rock in the middle of the Hinterlands. Green Sludges and Jade Oozes crawl all around it.\nCareful: Panthers move around the area in stealth.", ["Ride south-east to the Altar of Zul, the stepped Vilebranch temple in the south of the {zone:1425}, and climb to the top. {npc:7996} and {npc:8636} (elite, 50) stand up there: touch the top and come straight back down.\nCareful: Elite trolls guard the top platform, including {npc:7996} and {npc:8636}, along with several Vilebranch Soothsayers. The soothsayers cast spells and are linked to the rest of the group."] = "Ride south-east to the Altar of Zul, the stepped Vilebranch temple in the south of the Hinterlands, and climb to the top. Qiaga and Morta'gya the Keeper (elite, 50) stand up there: touch the top and come straight back down.\nCareful: Elite trolls guard the top platform, including Qiaga the Keeper and Morta'gya the Keeper, along with several Vilebranch Soothsayers. The soothsayers cast spells and are linked to the rest of the group.", ["{npc:7907}'s next errand goes to {zone:1446}: skip it."] = "Daryn's next errand goes to Tanaris: skip it.", ["{npc:8022}' next task, {quest:2991}, is a Zul'Farrak quest: only for the second run (Group 24), taken in the next step; otherwise skip it."] = "Thadius' next task, Nekrum's Medallion, is a Zul'Farrak quest: only for the second run (Group 24), taken in the next step; otherwise skip it.", ["{zone:1453}"] = "Stormwind City" },
			steps = {
				{
					title = "{quest:2989}",
					note = "Ride south-east to the Altar of Zul, the stepped Vilebranch temple in the south of the {zone:1425}, and climb to the top. {npc:7996} and {npc:8636} (elite, 50) stand up there: touch the top and come straight back down.\nCareful: Elite trolls guard the top platform, including {npc:7996} and {npc:8636}, along with several Vilebranch Soothsayers. The soothsayers cast spells and are linked to the rest of the group.",
					when = { { k = "onquest", q = { 2989 } } },
					goals = {
						{ t = "note", text = "Everyone at their own pace: what you already did ticks itself, the guide picks up where you are. Playing together? Group XP is best within 4 levels." },
						{ t = "goto", map = 1425, x = 49, y = 68.7, f = "e" },
						{ t = "complete", quest = 2989, title = "The Altar of Zul", map = 1425, x = 49, y = 68.7, f = "e" },
					},
				},
				{
					title = "The {item:9240} (second Zul'Farrak run)",
					note = "For {npc:7273}, one player of the group needs the {item:9240}. Kill {npc:7996} (elite 50) at the top of the Altar of Zul for the {item:9241}, then ride east to Jintha'Alor and fight up to the altar at its very top: use the {item:9241} there. Both temples are full of elite trolls of 46 to 50: the whole group goes. Keep the mallet in the bags until Group 24.",
					when = { { k = "group", q = 2770 }, { k = "onquest", q = { 2770 } } },
					goals = {
						{ t = "collect", item = 9241, itemName = "Sacred Mallet", count = 1, map = 1425, x = 48.6, y = 68.2, f = "e", optional = true, note = "{item:9241}: {npc:7996}", from = "Qiaga the Keeper", fromKind = "npc", fromRank = 1, fromId = 7996, fromNpcs = { { npc = 7996, npcName = "Qiaga the Keeper" } }, group = { kind = "elite", rank = 1 } },
						{ t = "use", item = 9241, itemName = "Sacred Mallet", map = 1425, x = 59.7, y = 77.8, f = "e", optional = true, note = "At the Jintha'Alor altar, the very top" },
						{ t = "collect", item = 9240, itemName = "Mallet of Zul'Farrak", count = 1, optional = true },
					},
				},
				{
					title = "{npc:5598} (Sunken Temple, optional)",
