				{
					title = "Sunken Temple (dungeon, optional): the Pool of Tears",
					note = "Ride north out of the {zone:1419} into the {zone:1435}, then east past Stonard (Horde) to the Pool of Tears. The temple lies under the water: swim down into it and find the dungeon's entrance inside.",
					when = { { k = "group", q = 1475 } },
					goals = {
						{ t = "note", text = "Group of 5, levels 50 to 55. Keep 3 free quest log slots. Share each quest with your group: click it in the quest log, then Share." },
